package palindrome

import (
	"errors"
	"fmt"
	"strconv"
)

// Product holds a palindromic product together with all of its
// factorizations within the given range.
type Product struct {
	Product      int
	Factorizations [][2]int
}

// Products finds the smallest and largest palindromic products of two
// factors within the inclusive range [fmin, fmax], along with all
// factor pairs that produce each.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, fmt.Errorf("fmin > fmax")
	}

	var min, max Product
	found := false

	for a := fmin; a <= fmax; a++ {
		for b := a; b <= fmax; b++ {
			p := a * b
			if !isPalindrome(p) {
				continue
			}
			if !found {
				min = Product{p, [][2]int{{a, b}}}
				max = Product{p, [][2]int{{a, b}}}
				found = true
				continue
			}
			if p < min.Product {
				min = Product{p, [][2]int{{a, b}}}
			} else if p == min.Product {
				min.Factorizations = append(min.Factorizations, [2]int{a, b})
			}
			if p > max.Product {
				max = Product{p, [][2]int{{a, b}}}
			} else if p == max.Product {
				max.Factorizations = append(max.Factorizations, [2]int{a, b})
			}
		}
	}

	if !found {
		return Product{}, Product{}, errors.New("no palindromes")
	}

	return min, max, nil
}

// isPalindrome reports whether n reads the same forwards and backwards.
func isPalindrome(n int) bool {
	s := strconv.Itoa(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}
